sys_variable_value.value:
/* global x_hccc_hoc_ohs */
(function(outputs, steps, params, stepResult, assertEqual) {
    var EXPECTED = {
        SITE: '131 Queen(131 Queen Street)',
        TIME: '0400',
        DESCRIPTION_OF_WHAT_HAPPENED: 'ATF Description',
        EMPLOYEE_TRAINING: 'Yes',
        OCCUPATION: 'ATF Title',
        EMPLOYEE_TEL: '000-000-000',
        SUPPLEMENTARY_PREVENTATIVE_MEASURES: 'ATFSupplementary',
        BRIEF_DESCRIPTION: 'ATFProperty',
        DESCRIPTION_INJURY: 'ATF Injury Description',
        TRAINING_SPECIFICATIONS: 'ATFTraining',
        CORRECTIVE_MEASURES: 'ATF Corrective Measures',
        REASON_FOR_NOT_TAKING_CORRECTIVE_MEASURES: 'ATFCorrective',
        WHSC_COMMENT: 'ATFWHSCComments',
        INVESTIGATOR_TEL: '000-000-000',
        INVESTIGATOR_FIRSTNAME: 'HocManagerPersona',
        INVESTIGATOR_TITLE: 'Test Manager',
        INVESTIGATOR_EMAIL: 'HocManagerPersona.Vax@parlissi.gc.ca',
        INVESTIGATOR_LASTNAME: 'Vax',
        EMPLOYEE_GENDER: 'M',
        COMMITTEE_TEL: '111-111-1111',
        EMPLOYEE_NAME_AND_ADDRESS: 'House of Commons\n111 Wellington Street\nOttawa, Ontario',
        TYPE_OF_OCCURENCE: '1',
        DIRECT_CAUSE_OF_HAZARDOUS_OCCURENCE: 'Defects of equipment, Worn, cracked, broken, etc.',
        EMPLOYEE_NAME: 'ATFOHSAdminLast, ATFOHSAdminFirst'
    };

    var STEP_SYS_ID = '52b5a37d1b67add09fde86acdd4bcb2d'; //Submit Record Porducer test step sys_id
    var record_sys_id = steps(STEP_SYS_ID).record_id; // Submitted Record Procucer record sys_id

    var caseGr = new GlideRecord('x_hccc_hoc_ohs_investigation_case');
    caseGr.get(record_sys_id);

    var annexString = gs.getMessageLang("x_hccc_hoc_ohs.annex", "en");
    var ohsmUtils = new x_hccc_hoc_ohs.HoCOHSMUtils();

    var returnedObj1 = ohsmUtils.getFieldFormattedString(caseGr.getValue("mng_inc_desc"), 100, 3, annexString);
    var returnedObj2 = ohsmUtils.getFieldFormattedString(caseGr.getValue("brief_description_and_estimated_cost"), 100, 2, annexString);
    var returnedObj3 = ohsmUtils.getFieldFormattedString(caseGr.getValue("supplementary_preventative_measures"), 100, 2, annexString);
    var returnedObj4 = ohsmUtils.getFieldFormattedString(caseGr.getValue("mng_desc_injury"), 60, 2, annexString);
    var returnedObj5 = ohsmUtils.getFieldFormattedString(caseGr.getValue("training_spec"), 50, 2, annexString);
    var returnedObj6 = ohsmUtils.getFieldFormattedString(caseGr.getValue("correct_meas_imp_date"), 100, 2, annexString);
    var returnedObj7 = ohsmUtils.getFieldFormattedString(caseGr.getValue("no_correct_meas_reas"), 100, 2, annexString);
    var returnedObj8 = ohsmUtils.getFieldFormattedString(caseGr.getValue("whsc_comments"), 100, 2, annexString);

    var supp_prev = returnedObj3.formattedString; //Field value "Supplementary preventative measures"
    var brief_desc = returnedObj2.formattedString; //Field value "Brief description and estimated costs"
    var desc_happened = returnedObj1.formattedString; //Field value "Description of what happened"
    var desc_inj = returnedObj4.formattedString; //Field value "Description of the injury"
    var training_spec = returnedObj5.formattedString; //Field value "Training specifications"
    var corrective_meas = returnedObj6.formattedString; //Field value "Corrective measures"
    var reason_corr = returnedObj7.formattedString; //Field value "Reasons for not taking corrective measures"
    var whsc_comm = returnedObj8.formattedString; //Field value "WHSC comments"

    var time = ohsmUtils.getTime(caseGr); //Field value "Site of hazardous occurence"
    var site = ohsmUtils.getLocationString(caseGr); //Field value "Date and time of hazardous occurence"
    var employeetraining = ohsmUtils.getEmployeeTrainingString(caseGr); //Field value "Did the employee receive training?"  
    var occupation = ohsmUtils.getPersonTitle(caseGr).toString(); // Field value of Subject person title
    var employee_tel = ohsmUtils.getEmployeetel(caseGr); //Field value Employee Telephone Number
    var investigator_tel = ohsmUtils.getInvestigator(caseGr, "number"); //Field value Investigator Telephone Number
    var invetsigator_first = ohsmUtils.getInvestigator(caseGr, "firstname"); //Field value Investigator Surname
    var investigator_last = ohsmUtils.getInvestigator(caseGr, "lastname"); //Field value Investigator Given Name
    var investigator_title = ohsmUtils.getInvestigator(caseGr, "title"); //Field value Investigator Title
    var investigator_email = ohsmUtils.getInvestigator(caseGr, "email"); //Field value Investigator Email
    var gender = ohsmUtils.getGender('Male'); //Field value Employee Gender - Testing mapped value of Male manually
    var committee_tel = ohsmUtils.getCommiteetel(caseGr); //Field value Comittee Telephone Number
    var empl_name = ohsmUtils.getEmplNameandMailing(); //Field value Employer's name and mailing address
    var type_occ = ohsmUtils.getTypeoccurence(caseGr, "Disability injury", "disab_injury"); //Field value "Type of Occurence" for Disability injury
    var hazardous_occ = ohsmUtils.getHazardousOcc(caseGr); //Field value "Direct causes of hazardous occurrence"
    var emp_name = ohsmUtils.getEmployeeName(caseGr); //Field value "Employee Name"

    var tempResult;
    var isPassing = true;

    function isMatchingExpectation(field, expectedValue, currentValue) {
        if (currentValue === expectedValue) {
            return {
                result: true,
                info: 'Field "' + field + '" value is correct.'
            };
        } else {
            return {
                result: false,
                info: 'Field "' + field + '" value is incorrect. Expected [' + expectedValue + '], instead got [' + currentValue + ']'
            };
        }
    }

    //Check value of field "Site of hazardous occurence" is correct
    tempResult = isMatchingExpectation('Site of hazardous occurence', EXPECTED.SITE, site);
    if (!tempResult.result) {
        gs.info(tempResult.info);
        isPassing = false;
    }

    //Check value "Date and time of hazardous occurence" of field is correct
    tempResult = isMatchingExpectation('Date and time of hazardous occurence', EXPECTED.TIME, time);
    if (!tempResult.result) {
        gs.info(tempResult.info);
        isPassing = false;
    }

    //Check value "Description of what happened" of field is correct
    tempResult = isMatchingExpectation('Description of what happened', EXPECTED.DESCRIPTION_OF_WHAT_HAPPENED, desc_happened);
    if (!tempResult.result) {
        gs.info(tempResult.info);
        isPassing = false;
    }

    //Check value of field "Did the employee receive training?" is correct
    tempResult = isMatchingExpectation('Did the employee receive training?', EXPECTED.EMPLOYEE_TRAINING, employeetraining);
    if (!tempResult.result) {
        gs.info(tempResult.info);
        isPassing = false;
    }

    //Check value of field "Occupation" is correct
    tempResult = isMatchingExpectation('Occupation', EXPECTED.OCCUPATION, occupation);
    if (!tempResult.result) {
        gs.info(tempResult.info);
        isPassing = false;
    }

    //Check value of field Employee Telephone is correct
    tempResult = isMatchingExpectation('Employee Telephone value', EXPECTED.EMPLOYEE_TEL, employee_tel);
    if (!tempResult.result) {
        gs.info(tempResult.info);
        isPassing = false;
    }

    //Check value of field "Supplementary preventative measures" is correct
    tempResult = isMatchingExpectation('Supplementary preventative measures', EXPECTED.SUPPLEMENTARY_PREVENTATIVE_MEASURES, supp_prev);
    if (!tempResult.result) {
        gs.info(tempResult.info);
        isPassing = false;
    }

    //Check value of field "Brief description and estimated costs" is correct
    tempResult = isMatchingExpectation('Brief description and estimated costs', EXPECTED.BRIEF_DESCRIPTION, brief_desc);
    if (!tempResult.result) {
        gs.info(tempResult.info);
        isPassing = false;
    }

    //Check value of field "Description of the injury" is correct
    tempResult = isMatchingExpectation('Description of the injury', EXPECTED.DESCRIPTION_INJURY, desc_inj);
    if (!tempResult.result) {
        gs.info(tempResult.info);
        isPassing = false;
    }

    //Check value of field "Training specifications" is correct
    tempResult = isMatchingExpectation('Training specifications', EXPECTED.TRAINING_SPECIFICATIONS, training_spec);
    if (!tempResult.result) {
        gs.info(tempResult.info);
        isPassing = false;
    }
    //Check value of field " Corrective measures" is correct
    tempResult = isMatchingExpectation('Corrective measures', EXPECTED.CORRECTIVE_MEASURES, corrective_meas);
    if (!tempResult.result) {
        gs.info(tempResult.info);
        isPassing = false;
    }
    //Check value of field "Reasons for not taking corrective measures" is correct
    tempResult = isMatchingExpectation('Reasons for not taking corrective measures', EXPECTED.REASON_FOR_NOT_TAKING_CORRECTIVE_MEASURES, reason_corr);
    if (!tempResult.result) {
        gs.info(tempResult.info);
        isPassing = false;
    }

    //Check value of field "WHSC comments" is correct
    tempResult = isMatchingExpectation('WHSC comments', EXPECTED.WHSC_COMMENT, whsc_comm);
    if (!tempResult.result) {
        gs.info(tempResult.info);
        isPassing = false;
    }

    //Check value of field Investigator Telephone Number is correct
    tempResult = isMatchingExpectation('Investigator Telephone Number', EXPECTED.INVESTIGATOR_TEL, investigator_tel);
    if (!tempResult.result) {
        gs.info(tempResult.info);
        isPassing = false;
    }

    //Check value of field Investigator Surname is correct
    tempResult = isMatchingExpectation('Investigator Surname', EXPECTED.INVESTIGATOR_FIRSTNAME, invetsigator_first);
    if (!tempResult.result) {
        gs.info(tempResult.info);
        isPassing = false;
    }

    //Check value of field Investigator title is correct
    tempResult = isMatchingExpectation('Investigator title', EXPECTED.INVESTIGATOR_TITLE, investigator_title);
    if (!tempResult.result) {
        gs.info(tempResult.info);
        isPassing = false;
    }

    //Check value of field Investigator Telephone Number is correct
    tempResult = isMatchingExpectation('Investigator email', EXPECTED.INVESTIGATOR_EMAIL, investigator_email);
    if (!tempResult.result) {
        gs.info(tempResult.info);
        isPassing = false;
    }

    //Check value of field Investigator Telephone Number is correct
    tempResult = isMatchingExpectation('Investigator Given Name', EXPECTED.INVESTIGATOR_LASTNAME, investigator_last);
    if (!tempResult.result) {
        gs.info(tempResult.info);
        isPassing = false;
    }

    //Check value of field Employee Gender is correct
    tempResult = isMatchingExpectation('Employee Gender', EXPECTED.EMPLOYEE_GENDER, gender);
    if (!tempResult.result) {
        gs.info(tempResult.info);
        isPassing = false;
    }

    //Check value of field Committee Telephone Number is correct
    tempResult = isMatchingExpectation('Committee Telephone Number', EXPECTED.COMMITTEE_TEL, committee_tel);
    if (!tempResult.result) {
        gs.info(tempResult.info);
        isPassing = false;
    }

    // Check value of field Employer's name and mailing address is correct
    tempResult = isMatchingExpectation('Employers name and mailing address', EXPECTED.EMPLOYEE_NAME_AND_ADDRESS, empl_name);
    if (!tempResult.result) {
        gs.info(tempResult.info);
        isPassing = false;
    }

    // Check value of field "Type of Occurence" is correct
    tempResult = isMatchingExpectation('Type of Occurence', EXPECTED.TYPE_OF_OCCURENCE, type_occ);
    if (!tempResult.result) {
        gs.info(tempResult.info);
        isPassing = false;
    }

    // Check value of field "Direct causes of hazardous occurrence" is correct
    tempResult = isMatchingExpectation('Direct causes of hazardous occurrence', EXPECTED.DIRECT_CAUSE_OF_HAZARDOUS_OCCURENCE, hazardous_occ);
    if (!tempResult.result) {
        gs.info(tempResult.info);
        isPassing = false;
    }

    // Check value of field "Employee Name" is correct
    tempResult = isMatchingExpectation('Employee Name', EXPECTED.EMPLOYEE_NAME, emp_name);
    if (!tempResult.result) {
        gs.info(tempResult.info);
        isPassing = false;
    }

    return isPassing;
})(outputs, steps, params, stepResult, assertEqual);
